index 9ba4aede..6469e3f4 100644
--- a/overrides/app/components/ui-kits/atoms/zimmInlineMessage/index.test.tsx
+++ b/overrides/app/components/ui-kits/atoms/zimmInlineMessage/index.test.tsx
@@ -90,4 +90,26 @@ describe('ZimmInlineMessage', () => {
     expect(screen.getByTestId('zimm-discount-label')).toBeInTheDocument();
     expect(screen.queryByTestId('zimm-inline-message')).not.toBeInTheDocument();
   });
+
+  // SFCC-795 plan step 3.6 (accessibility sweep): `id` omitted (e.g. the discount-label
+  // ZimmInlineMessage instance in product-item/index.tsx, which is never given one — see this
+  // prop's own JSDoc) renders no `id` attribute at all, not an empty string.
+  test('id omitted: root element has no id attribute', () => {
+    renderWithTheme(<ZimmInlineMessage variant="error" text="This item is unavailable" />);
+    expect(screen.getByTestId('zimm-inline-message')).not.toHaveAttribute('id');
+  });
+
+  // SFCC-795 plan step 3.6: id provided renders verbatim on the root element — the half of the
+  // id+aria-describedby pairing this atom owns (see this prop's own JSDoc for the other half,
+  // wired from product-item/index.tsx onto ZimmQuantityStepper's two buttons).
+  test('id provided: root element carries it verbatim', () => {
+    renderWithTheme(
+      <ZimmInlineMessage
+        variant="warning"
+        text="Maximum purchase quantity reached for this size"
+        id="cart-item-a1b2c3-message"
+      />,
+    );
+    expect(screen.getByTestId('zimm-inline-message')).toHaveAttribute('id', 'cart-item-a1b2c3-message');
+  });
 });

