   });
 });

+// SFCC-795 plan step 3.6 (accessibility sweep) AC6: the message describing this stepper's state
+// applies to the control as a whole, not one direction, so ariaDescribedBy is asserted on BOTH
+// buttons independently — not just "at least one", which would also pass if it were wired to only
+// one by mistake. Mutation-tested manually: temporarily dropping ariaDescribedBy from the
+// increment ZimmButton (index.tsx) while leaving decrement's in place failed the "both buttons"
+// assertion as expected (increment's aria-describedby came back null), then reverted.
+describe('ZimmQuantityStepper — ariaDescribedBy forwarding (AC6)', () => {
+  test('omitted: neither button carries aria-describedby', () => {
+    renderStepper({ quantity: 3, max: 5 });
+    expect(screen.getByRole('button', { name: DECREMENT_NAME })).not.toHaveAttribute('aria-describedby');
+    expect(screen.getByRole('button', { name: INCREMENT_NAME })).not.toHaveAttribute('aria-describedby');
+  });
+
+  test('provided: both buttons carry the exact same id', () => {
+    renderStepper({ quantity: 3, max: 5, ariaDescribedBy: 'zimm-inline-message-a1b2c3' });
+    expect(screen.getByRole('button', { name: DECREMENT_NAME })).toHaveAttribute(
+      'aria-describedby',
+      'zimm-inline-message-a1b2c3',
+    );
+    expect(screen.getByRole('button', { name: INCREMENT_NAME })).toHaveAttribute(
+      'aria-describedby',
+      'zimm-inline-message-a1b2c3',
+    );
+  });
+});
+
+// SFCC-795 plan step 3.6 (accessibility sweep) AC3: no existing test in this file (or anywhere
+// in product-item's own suite) asserted the value display's aria-live before this — index.tsx's
+// own comment says a shopper-caused change is announced, but that was never actually proven
+// against a render. Mutation-tested manually: removing `aria-live="polite"` from index.tsx's
+// value span while iterating this test failed it as expected, confirming this is not a
+// vacuously-true assertion.
+describe('ZimmQuantityStepper — quantity announces via a live region (AC3)', () => {
+  test('the value display carries aria-live="polite"', () => {
+    renderStepper({ quantity: 3, max: 5 });
+    expect(screen.getByText('3')).toHaveAttribute('aria-live', 'polite');
+  });
+});
+
+// SFCC-795 plan step 3.6 (accessibility sweep) AC4: every existing test in this file drives the
+// buttons via .click() (a synthesised pointer click, per Testing Library's own docs for both
+// fireEvent.click and userEvent.click) — none proves Tab reaches them or that Enter/Space (a real
+// keyboard interaction, no pointer event at all) activates them. Both tests below were
+// mutation-tested manually against index.tsx, then reverted: the first, by temporarily replacing
+// handleDecrement/handleIncrement's bodies with a bare `return` (failed both activation
+// assertions as expected — Enter/Space genuinely drive the same callback path a click does,
+// rather than the assertions being satisfied some other way); the second, by temporarily adding
+// `disabled={decrementInert}` alongside the existing `ariaDisabled` prop on the decrement
+// ZimmButton (failed the `toHaveFocus()` assertion as expected — Tab landed on increment instead,
+// confirming this test actually distinguishes `ariaDisabled` from native `disabled`, not just
+// asserting something vacuously true).
+describe('ZimmQuantityStepper — keyboard-only operation (AC4)', () => {
+  test('Tab reaches decrement then increment in order, and Enter/Space activate them — no pointer event involved', async () => {
+    const { onDecrement, onIncrement } = renderStepper({ quantity: 3, max: 5 });
+
+    await userEvent.tab();
+    expect(screen.getByRole('button', { name: DECREMENT_NAME })).toHaveFocus();
+    await userEvent.keyboard('{Enter}');
+    expect(onDecrement).toHaveBeenCalledWith(2);
+
+    await userEvent.tab();
+    expect(screen.getByRole('button', { name: INCREMENT_NAME })).toHaveFocus();
+    await userEvent.keyboard(' ');
+    expect(onIncrement).toHaveBeenCalledWith(4);
+  });
+
+  test('an inert (aria-disabled) button stays reachable via Tab, but Enter does not call its handler', async () => {
+    // Decrement is inert at the min boundary (quantity === min) — see the State 1 describe block
+    // above. `ariaDisabled`, not the native `disabled` attribute, is what keeps it tabbable at all
+    // (ZimmButton's own documented contract) — this proves that contract holds under real keyboard
+    // interaction, not only under fireEvent.click.
+    const { onDecrement } = renderStepper({ quantity: 1, max: 5 });
+
+    await userEvent.tab();
+    expect(screen.getByRole('button', { name: DECREMENT_NAME })).toHaveFocus();
+    await userEvent.keyboard('{Enter}');
+    expect(onDecrement).not.toHaveBeenCalled();
+  });
+});
+
 /**
  * States 5 and 7 are both about ZimmButton's own `icon` variant/size — a Tier 2 file this build
  * step composes but does not modify (see index.tsx's docblock). Reading the exported recipe

