1	import React, { useCallback, useEffect, useId, useRef } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';
4	import { useZimmDropdown } from 'app/hooks/useZimmDropdown';
5	
6	/** State injected into the renderItems render prop. */
7	export type ZimmDropdownRenderState = {
8	  focusedIndex: number | null;
9	  close: () => void;
10	  /** The trigger element's id — use as aria-labelledby on a role="listbox" inside renderItems. */
11	  triggerId: string;
12	  /**
13	   * The panel element's id. Derive each option's own id from it as
14	   * `${panelId}-option-${index}` — ZimmDropdown programmatically focuses the element with
15	   * that id when the user arrow-keys through options.
16	   */
17	  panelId: string;
18	};
19	
20	/** Builds the option id — ZimmDropdown programmatically focuses the element with this id. */
21	export const getDropdownOptionId = (panelId: string, index: number) => `${panelId}-option-${index}`;
22	
23	type ZimmDropdownProps = {
24	  /** Accessible label; shown as the trigger label when no value is selected. */
25	  label: string;
26	  /**
27	   * Currently selected value text. When provided the label floats above it.
28	   * Pass `undefined` to show the label in the unselected position.
29	   */
30	  value?: string;
31	  variant?: 'flush' | 'outline';
32	  inverse?: boolean;
33	  disabled?: boolean;
34	  hasError?: boolean;
35	  errorMessage?: string;
36	  helperText?: string;
37	  /** Total item count — used for default linear Arrow-key navigation. */
38	  itemCount?: number;
39	  /**
40	   * Override Arrow navigation. Receives current focusedIndex and direction;
41	   * returns the new index. Defaults to clamped linear 0..itemCount-1 traversal.
42	   */
43	  navigateTo?: (from: number | null, direction: 1 | -1) => number | null;
44	  /**
45	   * Called when Enter is pressed on a focused item index. ZimmDropdown closes
46	   * the panel automatically after calling this.
47	   */
48	  onItemSelect?: (index: number) => void;
49	  /** Renders panel content; receives focusedIndex, a close handle, and the trigger id. */
50	  renderItems?: (state: ZimmDropdownRenderState) => React.ReactNode;
51	  /**
52	   * Rendered to the right of the trigger button in the same row.
53	   * The panel opens below the FULL row (trigger + this slot) — use for inline controls
54	   * that must sit beside the trigger, e.g. the "Find your size" link in ZimmSizeSelector.
55	   */
56	  triggerRowRight?: React.ReactNode;
57	  /** Rendered after the panel and before any helper/error text. */
58	  footer?: React.ReactNode;
59	  /** Stable id used to wire aria-controls and aria-describedby. Defaults to a per-mount uid. */
60	  id?: string;
61	  /**
62	   * Called with the trigger button element on mount and null on unmount.
63	   * Use to forward a ref to the trigger for programmatic focus (e.g. A4 — return focus
64	   * to the trigger when an error fires outside the dropdown).
65	   */
66	  triggerCallbackRef?: (el: HTMLButtonElement | null) => void;
67	};
68	
69	/**
70	 * Generic dropdown atom — trigger row + panel shell + keyboard navigation.
71	 * Supports flush (bottom border) and outline (full border) variants.
72	 * Pass content via `renderItems`; receive `focusedIndex` to style individual items.
73	 *
74	 * All styling lives in `zimmDropdown.css.ts`.
75	 */
76	export const ZimmDropdown = ({
77	  label,
78	  value,
79	  variant = 'flush',
80	  inverse = false,
81	  disabled = false,
82	  hasError = false,
83	  errorMessage,
84	  helperText,
85	  itemCount = 0,
86	  navigateTo,
87	  onItemSelect,
88	  renderItems,
89	  triggerRowRight,
90	  footer,
91	  id,
92	  triggerCallbackRef,
93	}: ZimmDropdownProps) => {
94	  // useId() is SSR-safe: server and client produce the same id, avoiding hydration mismatches
95	  // that Math.random() would cause when aria-controls/aria-describedby cross the render boundary.
96	  const generatedId = useId();
97	  const resolvedId = id ?? generatedId;
98	
99	  const triggerId = `${resolvedId}-trigger`;
100	  const panelId = `${resolvedId}-panel`;
101	  const helperId = `${resolvedId}-helper`;
102	  const errorId = `${resolvedId}-error`;
103	
104	  const {
105	    isOpen,
106	    focusedIndex,
107	    ref,
108	    toggle,
109	    close,
110	    onKeyDown: hookOnKeyDown,
111	  } = useZimmDropdown({
112	    itemCount,
113	    navigateTo,
114	  });
115	
116	  const triggerRef = useRef<HTMLButtonElement | null>(null);
117	
118	  const filled = value !== undefined && value !== '';
119	  const focused = isOpen;
120	
121	  const styles = useMultiStyleConfig('ZimmDropdown', {
122	    variant,
123	    inverse,
124	    disabled,
125	    hasError,
126	    focused,
127	    filled,
128	  });
129	
130	  // Move real DOM focus into the option element when the user arrow-keys through the list.
131	  useEffect(() => {
132	    if (!isOpen || focusedIndex === null) return;
133	    const optionEl = document.getElementById(getDropdownOptionId(panelId, focusedIndex));
134	    optionEl?.focus();
135	  }, [isOpen, focusedIndex, panelId]);
136	
137	  // Return focus to the trigger after mouse-click selection or Escape, so keyboard users
138	  // don't lose their place in the page's tab order after closing the panel.
139	  const closeAndReturnFocus = useCallback(() => {
140	    close();
141	    // Timeout of 0 lets React flush the panel unmount before re-focusing the trigger,
142	    // preventing a race where focus() fires on a node that's about to be removed.
143	    setTimeout(() => triggerRef.current?.focus(), 0);
144	  }, [close]);
145	
146	  const handleKeyDown = (e: React.KeyboardEvent<HTMLElement>) => {
147	    // A3 — Enter *or* Space selects the focused option. preventDefault() on Space is required:
148	    // without it the trigger <button> would also fire its own click and re-toggle the panel.
149	    if ((e.key === 'Enter' || e.key === ' ') && isOpen && focusedIndex !== null) {
150	      e.preventDefault();
151	      onItemSelect?.(focusedIndex);
152	      closeAndReturnFocus();
153	    } else if (e.key === 'Escape' && isOpen) {
154	      hookOnKeyDown(e); // calls close()
155	      triggerRef.current?.focus();
156	    } else {
157	      hookOnKeyDown(e);
158	    }
159	  };
160	
161	  const ariaDescribedBy =
162	    [helperText && !hasError && helperId, hasError && errorMessage && errorId].filter(Boolean).join(' ') || undefined;
163	
164	  return (
165	    <chakra.div __css={styles.root} ref={ref}>
166	      {/* Trigger row — trigger button + optional right-side slot (e.g. "Find your size").
167	          Panel renders BELOW this full row so it spans the entire root width. */}
168	      <chakra.div __css={styles.triggerRow}>
169	        <chakra.button
170	          ref={(el) => {
171	            triggerRef.current = el;
172	            triggerCallbackRef?.(el);
173	          }}
174	          id={triggerId}
175	          type="button"
176	          aria-label={filled ? `${label}: ${value}` : undefined}
177	          aria-expanded={isOpen}
178	          aria-haspopup="listbox"
179	          aria-controls={panelId}
180	          aria-describedby={ariaDescribedBy}
181	          disabled={disabled}
182	          __css={styles.trigger}
183	          onClick={disabled ? undefined : toggle}
184	          onKeyDown={disabled ? undefined : handleKeyDown}
185	        >
186	          {/* Figma: selected value fully replaces the placeholder — no floating label. */}
187	          <chakra.span __css={styles.content}>
188	            <chakra.span __css={styles.label}>{filled ? value : label}</chakra.span>
189	          </chakra.span>
190	          <chakra.span
191	            __css={{
192	              ...styles.chevron,
193	              transform: isOpen ? 'rotate(180deg)' : 'rotate(0deg)',
194	            }}
195	            aria-hidden={true}
196	          >
197	            <ZimmIcon type="chevron-down" size="sm" aria-hidden={true} />
198	          </chakra.span>
199	        </chakra.button>
200	        {triggerRowRight}
201	      </chakra.div>
202	
203	      {/* Panel — sibling of the trigger row, spans the full root width (Figma 6967:13860). */}
204	      {isOpen && renderItems && (
205	        <chakra.div id={panelId} __css={styles.panel} onKeyDown={disabled ? undefined : handleKeyDown}>
