import React, { useCallback, useEffect, useId, useRef } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';
import { useZimmDropdown } from 'app/hooks/useZimmDropdown';

/** State injected into the renderItems render prop. */
export type ZimmDropdownRenderState = {
  focusedIndex: number | null;
  close: () => void;
  /** The trigger element's id — use as aria-labelledby on a role="listbox" inside renderItems. */
  triggerId: string;
  /**
   * The panel element's id. Derive each option's own id from it as
   * `${panelId}-option-${index}` — ZimmDropdown programmatically focuses the element with
   * that id when the user arrow-keys through options.
   */
  panelId: string;
};

/** Builds the option id — ZimmDropdown programmatically focuses the element with this id. */
export const getDropdownOptionId = (panelId: string, index: number) => `${panelId}-option-${index}`;

type ZimmDropdownProps = {
  /** Accessible label; shown as the trigger label when no value is selected. */
  label: string;
  /**
   * Currently selected value text. When provided the label floats above it.
   * Pass `undefined` to show the label in the unselected position.
   */
  value?: string;
  variant?: 'flush' | 'outline';
  inverse?: boolean;
  disabled?: boolean;
  hasError?: boolean;
  errorMessage?: string;
  helperText?: string;
  /** Total item count — used for default linear Arrow-key navigation. */
  itemCount?: number;
  /**
   * Override Arrow navigation. Receives current focusedIndex and direction;
   * returns the new index. Defaults to clamped linear 0..itemCount-1 traversal.
   */
  navigateTo?: (from: number | null, direction: 1 | -1) => number | null;
  /**
   * Called when Enter is pressed on a focused item index. ZimmDropdown closes
   * the panel automatically after calling this.
   */
  onItemSelect?: (index: number) => void;
  /** Renders panel content; receives focusedIndex, a close handle, and the trigger id. */
  renderItems?: (state: ZimmDropdownRenderState) => React.ReactNode;
  /**
   * Rendered to the right of the trigger button in the same row.
   * The panel opens below the FULL row (trigger + this slot) — use for inline controls
   * that must sit beside the trigger, e.g. the "Find your size" link in ZimmSizeSelector.
   */
  triggerRowRight?: React.ReactNode;
  /** Rendered after the panel and before any helper/error text. */
  footer?: React.ReactNode;
  /** Stable id used to wire aria-controls and aria-describedby. Defaults to a per-mount uid. */
  id?: string;
  /**
   * Called with the trigger button element on mount and null on unmount.
   * Use to forward a ref to the trigger for programmatic focus (e.g. A4 — return focus
   * to the trigger when an error fires outside the dropdown).
   */
  triggerCallbackRef?: (el: HTMLButtonElement | null) => void;
};

/**
 * Generic dropdown atom — trigger row + panel shell + keyboard navigation.
 * Supports flush (bottom border) and outline (full border) variants.
 * Pass content via `renderItems`; receive `focusedIndex` to style individual items.
 *
 * All styling lives in `zimmDropdown.css.ts`.
 */
export const ZimmDropdown = ({
  label,
  value,
  variant = 'flush',
  inverse = false,
  disabled = false,
  hasError = false,
  errorMessage,
  helperText,
  itemCount = 0,
  navigateTo,
  onItemSelect,
  renderItems,
  triggerRowRight,
  footer,
  id,
  triggerCallbackRef,
}: ZimmDropdownProps) => {
  // useId() is SSR-safe: server and client produce the same id, avoiding hydration mismatches
  // that Math.random() would cause when aria-controls/aria-describedby cross the render boundary.
  const generatedId = useId();
  const resolvedId = id ?? generatedId;

  const triggerId = `${resolvedId}-trigger`;
  const panelId = `${resolvedId}-panel`;
  const helperId = `${resolvedId}-helper`;
  const errorId = `${resolvedId}-error`;

  const {
    isOpen,
    focusedIndex,
    ref,
    toggle,
    close,
    onKeyDown: hookOnKeyDown,
  } = useZimmDropdown({
    itemCount,
    navigateTo,
  });

  const triggerRef = useRef<HTMLButtonElement | null>(null);

  const filled = value !== undefined && value !== '';
  const focused = isOpen;

  const styles = useMultiStyleConfig('ZimmDropdown', {
    variant,
    inverse,
    disabled,
    hasError,
    focused,
    filled,
  });

  // Move real DOM focus into the option element when the user arrow-keys through the list.
  useEffect(() => {
    if (!isOpen || focusedIndex === null) return;
    const optionEl = document.getElementById(getDropdownOptionId(panelId, focusedIndex));
    optionEl?.focus();
  }, [isOpen, focusedIndex, panelId]);

  // Return focus to the trigger after mouse-click selection or Escape, so keyboard users
  // don't lose their place in the page's tab order after closing the panel.
  const closeAndReturnFocus = useCallback(() => {
    close();
    // Timeout of 0 lets React flush the panel unmount before re-focusing the trigger,
    // preventing a race where focus() fires on a node that's about to be removed.
    setTimeout(() => triggerRef.current?.focus(), 0);
  }, [close]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLElement>) => {
    // A3 — Enter *or* Space selects the focused option. preventDefault() on Space is required:
    // without it the trigger <button> would also fire its own click and re-toggle the panel.
    if ((e.key === 'Enter' || e.key === ' ') && isOpen && focusedIndex !== null) {
      e.preventDefault();
      onItemSelect?.(focusedIndex);
      closeAndReturnFocus();
    } else if (e.key === 'Escape' && isOpen) {
      hookOnKeyDown(e); // calls close()
      triggerRef.current?.focus();
    } else {
      hookOnKeyDown(e);
    }
  };

  const ariaDescribedBy =
    [helperText && !hasError && helperId, hasError && errorMessage && errorId].filter(Boolean).join(' ') || undefined;

  return (
    <chakra.div __css={styles.root} ref={ref}>
      {/* Trigger row — trigger button + optional right-side slot (e.g. "Find your size").
          Panel renders BELOW this full row so it spans the entire root width. */}
      <chakra.div __css={styles.triggerRow}>
        <chakra.button
          ref={(el) => {
            triggerRef.current = el;
            triggerCallbackRef?.(el);
          }}
          id={triggerId}
          type="button"
          aria-label={filled ? `${label}: ${value}` : undefined}
          aria-expanded={isOpen}
          aria-haspopup="listbox"
          aria-controls={panelId}
          aria-describedby={ariaDescribedBy}
          disabled={disabled}
          __css={styles.trigger}
          onClick={disabled ? undefined : toggle}
          onKeyDown={disabled ? undefined : handleKeyDown}
        >
          {/* Figma: selected value fully replaces the placeholder — no floating label. */}
          <chakra.span __css={styles.content}>
            <chakra.span __css={styles.label}>{filled ? value : label}</chakra.span>
          </chakra.span>
          <chakra.span
            __css={{
              ...styles.chevron,
              transform: isOpen ? 'rotate(180deg)' : 'rotate(0deg)',
            }}
            aria-hidden={true}
          >
            <ZimmIcon type="chevron-down" size="sm" aria-hidden={true} />
          </chakra.span>
        </chakra.button>
        {triggerRowRight}
      </chakra.div>

      {/* Panel — sibling of the trigger row, spans the full root width (Figma 6967:13860). */}
      {isOpen && renderItems && (
        <chakra.div id={panelId} __css={styles.panel} onKeyDown={disabled ? undefined : handleKeyDown}>
          {renderItems({ focusedIndex, close: closeAndReturnFocus, triggerId, panelId })}
        </chakra.div>
      )}

      {footer}

      {helperText && !hasError && (
        <chakra.p id={helperId} __css={styles.helper}>
          {helperText}
        </chakra.p>
      )}
      {hasError && errorMessage && (
        <chakra.p id={errorId} role="alert" __css={styles.error}>
          {errorMessage}
        </chakra.p>
      )}
    </chakra.div>
  );
};

